# Server Script: Assign SO Item ID to Sales Invoice Items
# DocType: Sales Invoice | Event: Before Save

def assign_so_detail(doc):
    for item in doc.items:
        # Only process rows linked to a Sales Order
        if not item.sales_order:
            continue

        # Skip if so_detail is already correctly set
        if item.so_detail:
            # Validate it still belongs to this SO + item_code
            existing = frappe.db.get_value(
                "Sales Order Item",
                item.so_detail,
                ["parent", "item_code"],
                as_dict=True
            )
            if existing and existing.parent == item.sales_order and existing.item_code == item.item_code:
                continue  # Already valid, skip

        # Find the matching Sales Order Item
        so_item_name = frappe.db.get_value(
            "Sales Order Item",
            {
                "parent": item.sales_order,
                "item_code": item.item_code,
                "docstatus": ["!=", 2]  # exclude cancelled
            },
            "name"
        )

        if so_item_name:
            item.so_detail = so_item_name
        else:
            frappe.msgprint(
                f"⚠️ Could not find matching Sales Order Item for {item.item_code} in {item.sales_order}",
                alert=True
            )

# Run on Save
